import { isEmpty } from 'lodash-es';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';

export const WalletStatus = ({ desc }: { desc?: string }) => {
  const { data: userRes } = useGetUserInfoQuery();
  const isWalletBlocked = userRes?.tbCstmrMastr?.isWalletBlocked;
  const isBizAccount = !isEmpty(userRes?.tbCstmrMastr?.ewaBizNo);

  return (
    <>
      {isBizAccount && <span className="main-wallet-badge-shop">사업자</span>}
      {isWalletBlocked && <span className="main-wallet-status">{desc || '거래 제한'}</span>}
    </>
  );
};
